using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class ActiveMilitarySuccessionTests
{
    static readonly EntityId Home=new("site:kofu"),Owner=new("org:takeda"),Old=new("person:shingen"),Heir=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    static WorldSession Start(bool retired=false)=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],retired?Old.Value:Heir.Value,42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:HouseSuccession.Policy));
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void At(WorldSession s,long t){while(s.Seconds<t){var n=s.Seconds;s.SetPaused(false);s.AdvanceTo(t,100000);Assert.True(s.Seconds>n);}}
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Good(s.Open(s.PlayerControl,m.Id,s.Revision));}
    static NewMilitaryInput Input(WorldSession s,NewMilitaryAction a)=>new(new("request:military-succession/"+s.Revision+"/"+a),a);
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0)=>Good(s.DecideNewMilitary(Input(s,a) with{Amount=amount},s.PlayerControl,s.Revision));
    static NewMilitaryInput Request(WorldSession s,bool handover=false)=>Input(s,NewMilitaryAction.Request) with{LedgerPolicy=NewGameMilitary.LedgerIdentityContract,AuthorityPolicy=NewGameMilitary.AuthorityContract,ObservationPolicy=NewGameMilitary.ObservationContract,CycleContract=s.DiagnosticSnapshot().NewMilitary!=null?NewGameMilitary.RenewalContract:null,IssuerPolicy=handover?NewGameMilitary.IssuerSuccessionContract:null};
    static void Succeed(WorldSession s){var id=new EntityId("request:military-head/"+s.Revision);Good(s.ManageHouseSuccession(new(id,HouseSuccessionAction.Nominate,Owner,Heir){MilitaryPolicy=NewGameMilitary.CanRetainActiveForSuccession(s.DiagnosticSnapshot(),s.PlayerControl,Owner,Home,s.Seconds,s.Revision)?NewGameMilitary.ActiveSuccessionContract:null},s.PlayerControl,s.Revision));Good(s.ManageHouseSuccession(new(new("request:military-head-confirm/"+s.Revision),HouseSuccessionAction.Confirm,Owner,Original:id),s.PlayerControl,s.Revision));At(s,s.Seconds+1);}
    static WorldSession Closed(bool open=true,bool retired=false){var s=Start(retired);Good(s.DecideNewMilitary(Request(s),s.PlayerControl,s.Revision));At(s,s.Seconds+2);Open(s);At(s,s.Seconds+NewGameMilitary.OfferSeconds+3);if(open)Open(s);return s;}
    static WorldSession Changed(){var s=Closed();Succeed(s);return s;}
    static WorldSession Assumed(){var s=Changed();Good(s.DecideNewMilitary(Request(s,true),s.PlayerControl,s.Revision));return s;}
    static void Permit(WorldSession s){At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Pickup);}
    static void Rice(WorldSession s,long kg)=>Good(s.ManageMilitaryRice(new(new("request:succession-rice/"+s.Revision),NewGameMilitary.DepotFor(s.DiagnosticSnapshot()),kg),s.PlayerControl,s.Revision));
    static void Finish(WorldSession s){Send(s,NewMilitaryAction.Report);At(s,s.Seconds+2);Send(s,NewMilitaryAction.Return);At(s,s.Seconds+2);Open(s);}

    static WorldSession Holding(bool retired=false){var s=Start(retired);Good(s.DecideNewMilitary(Request(s),s.PlayerControl,s.Revision));Permit(s);Rice(s,50);Send(s,NewMilitaryAction.Load,20*86400L);s.SetPaused(true);return s;}
    static ActiveMilitaryInput Agreement(WorldSession s)=>new(new("request:active-military/"+s.Revision),NewGameMilitary.Cases(s.DiagnosticSnapshot()).Last().Id);
    static void Agree(WorldSession s)=>Good(s.AgreeActiveMilitary(Agreement(s),s.PlayerControl,s.Revision));
    [Theory][InlineData(false)][InlineData(true)]public void OfficeChangeRetainsActualSameArmyAndOldIssuerUntilSeparateAgreement(bool retired){var s=Holding(retired);var before=s.DiagnosticSnapshot();Succeed(s);var w=s.DiagnosticSnapshot();Assert.Equal(Heir,HouseSuccession.Head(w,Owner));Assert.Equal(Old,NewGameMilitary.CasePrincipal(w));Assert.Equal(before.NewMilitary!.Terms,w.NewMilitary!.Terms);Assert.Equal(ContractJson.Write(before.ResourceLots),ContractJson.Write(w.ResourceLots));Assert.Equal(ContractJson.Write(before.Units),ContractJson.Write(w.Units));Assert.True(s.CanAgreeActiveMilitary());new WorldSession(w);}
    [Theory][InlineData(false)][InlineData(true)]public void ExplicitAgreementChangesOnlyFutureIssuerAndPlacementMandate(bool retired){var s=Holding(retired);Succeed(s);var before=s.DiagnosticSnapshot();var i=Agreement(s);Good(s.AgreeActiveMilitary(i,s.PlayerControl,s.Revision));var w=s.DiagnosticSnapshot();Assert.Equal(Heir,NewGameMilitary.CasePrincipal(w));Assert.Equal(Old,NewGameMilitary.CasePrincipal(w,before.ElapsedSeconds,before.CommitSequence));Assert.Equal(before.NewMilitary!.Terms,w.NewMilitary!.Terms);Assert.Equal(ContractJson.Write(before.ResourceLots),ContractJson.Write(w.ResourceLots));Assert.Equal(ContractJson.Write(before.Units),ContractJson.Write(w.Units));Assert.Equal(ContractJson.Write(before.Messaging.Messages),ContractJson.Write(w.Messaging.Messages));Assert.Equal(ContractJson.Write(before.NewMilitary.Authority!.Proofs),ContractJson.Write(w.NewMilitary.Authority!.Proofs));var row=w.NewMilitary.ActiveSuccession!.Entries.Single();Assert.Equal(Old,row.Previous);Assert.Equal(Heir,row.Principal);var grants=w.NewMilitary.Authority.Grants;Assert.Equal(2,grants.Length);Assert.Equal(Old,grants[0].Mandate.Principal);Assert.Equal(row.At,grants[0].Mandate.Until);Assert.Equal(row.Revision,grants[0].UntilRevision);Assert.Equal(Heir,grants[1].Mandate.Principal);Assert.False(NewGameMilitary.ScopedAuthorityAllows(grants[0],i.Case,s.PlayerControl,w.NewMilitary.Terms.Army,w.Units[0].Id,RegionalAction.Move,row.At,row.Revision));Assert.True(NewGameMilitary.ScopedAuthorityAllows(grants[1],i.Case,s.PlayerControl,w.NewMilitary.Terms.Army,w.Units[0].Id,RegionalAction.Move,row.At,row.Revision));new WorldSession(w);}
    [Theory][InlineData(false)][InlineData(true)]public void ActualFormationReturnReportAndSettlementUseNewIssuerWithoutReborrowing(bool retired){var s=Holding(retired);Succeed(s);Agree(s);Send(s,NewMilitaryAction.Deploy);Good(s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(NewGameMilitary.Anchor(s.DiagnosticSnapshot()).X-12000,NewGameMilitary.Anchor(s.DiagnosticSnapshot()).Y+4000),B=new(NewGameMilitary.Anchor(s.DiagnosticSnapshot()).X+12000,NewGameMilitary.Anchor(s.DiagnosticSnapshot()).Y+4000)},s.PlayerControl,s.Revision));At(s,s.Seconds+20);Send(s,NewMilitaryAction.Recall);At(s,s.Seconds+50);Assert.True(NewGameMilitary.View(s.DiagnosticSnapshot()).CanEnter);Send(s,NewMilitaryAction.Enter);var amount=NewGameMilitary.View(s.DiagnosticSnapshot()).Carry;Send(s,NewMilitaryAction.Unload,amount);Send(s,NewMilitaryAction.Report);var report=s.DiagnosticSnapshot().Messaging.Messages.Last(m=>m.Kind=="new-military-report");Assert.Equal(Heir.Value,report.RecipientId);At(s,s.Seconds+2);Send(s,NewMilitaryAction.Return);At(s,s.Seconds+2);Open(s);Assert.False(NewGameMilitary.View(s.DiagnosticSnapshot()).Custody);Assert.Equal(Heir,NewGameMilitary.CasePrincipal(s.DiagnosticSnapshot()));Assert.Equal(100,s.DiagnosticSnapshot().Units.Sum(u=>u.Soldiers));Assert.Single(NewGameMilitary.Cases(s.DiagnosticSnapshot()));var returned=s.DiagnosticSnapshot().NewMilitary!.Events.Last(e=>e.Effect==MilitaryEffect.Returned);Assert.Equal(Heir.Value,s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==returned.Message).SenderId);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void NoOptInDoesNotLoosenTheOldBusySuccessionRule(){var s=Holding();var id=new EntityId("request:active-without-opt-in");Good(s.ManageHouseSuccession(new(id,HouseSuccessionAction.Nominate,Owner,Heir),s.PlayerControl,s.Revision));Assert.Equal(ResultCode.NotAvailable,s.ManageHouseSuccession(new(new("request:active-without-opt-in-confirm"),HouseSuccessionAction.Confirm,Owner,Original:id),s.PlayerControl,s.Revision).Code);Assert.Equal(Old,HouseSuccession.Head(s.DiagnosticSnapshot(),Owner));}
    [Fact]public void DeployedArmyCannotUseTheLocalAssembledSuccessionScope(){var s=Holding();Send(s,NewMilitaryAction.Deploy);var w=s.DiagnosticSnapshot();Assert.False(NewGameMilitary.CanRetainActiveForSuccession(w,s.PlayerControl,Owner,Home,s.Seconds,s.Revision));Assert.False(s.CanAgreeActiveMilitary());}
    [Fact]public void DuplicateConflictWrongActorAndStaleViewDoNotRepeatAgreement(){var s=Holding();Succeed(s);var i=Agreement(s);Assert.Equal(ResultCode.NotAvailable,s.AgreeActiveMilitary(i,Old,s.Revision).Code);Assert.Equal(ResultCode.StateChanged,s.AgreeActiveMilitary(i,s.PlayerControl,s.Revision-1).Code);Good(s.AgreeActiveMilitary(i,s.PlayerControl,s.Revision));Assert.Equal(ResultCode.AlreadyAccepted,s.AgreeActiveMilitary(i,s.PlayerControl,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.AgreeActiveMilitary(i with{Case=new("request:wrong-case")},s.PlayerControl,s.Revision).Code);Assert.False(s.CanAgreeActiveMilitary());Assert.Single(s.DiagnosticSnapshot().NewMilitary!.ActiveSuccession!.Entries);}
    [Fact]public void AnUnchangedHeadCannotCreateAnActiveSuccession(){var s=Holding();Assert.False(s.CanAgreeActiveMilitary());Assert.Equal(ResultCode.NotAvailable,s.AgreeActiveMilitary(Agreement(s),s.PlayerControl,s.Revision).Code);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void ForgedActiveProvenanceCannotLoad(int n){var s=Holding();Succeed(s);Agree(s);var w=s.DiagnosticSnapshot();var e=w.NewMilitary!.ActiveSuccession!.Entries.Single();w.NewMilitary.ActiveSuccession.Entries[0]=n switch{0=>e with{Principal=Old},1=>e with{Previous=Heir},2=>e with{Army=new("army:forged")},3=>e with{Source=e.Source with{Office=new("office:forged")}},_=>e with{Revision=e.Revision-1}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData("Policy")][InlineData("Entries")]public void OptionalExtensionDoesNotMakeItsOwnRequiredFieldsOptional(string field){var s=Holding();Succeed(s);Agree(s);var node=System.Text.Json.Nodes.JsonNode.Parse(ContractJson.Write(s.DiagnosticSnapshot()))!;node["NewMilitary"]!["ActiveSuccession"]!.AsObject().Remove(field);Assert.Throws<InvalidDataException>(()=>ContractJson.Read<ContractWorld>(System.Text.Encoding.UTF8.GetBytes(node.ToJsonString())));}
    [Fact]public void OldCaseAndArmyOwnershipRemainAfterAgreement(){var s=Holding(true);Succeed(s);var before=s.DiagnosticSnapshot();Agree(s);var w=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(before.NewMilitary!.Binding),ContractJson.Write(w.NewMilitary!.Binding));Assert.Equal(before.ResourceLots.Select(l=>l.Owner),w.ResourceLots.Select(l=>l.Owner));Assert.Equal(before.Units.Select(u=>u.Army),w.Units.Select(u=>u.Army));Assert.Equal(Old,w.NewMilitary.Terms.Principal);Assert.Equal(Heir,NewGameMilitary.CasePrincipal(w));}

    static void ChangeHouse(WorldSession s,string node,string lord){if(NewGameService.View(s.DiagnosticSnapshot()).Principal!=null){var current=NewGameService.View(s.DiagnosticSnapshot()).Cases.Last(c=>c.Principal==NewGameService.View(s.DiagnosticSnapshot()).Principal);Assert.Equal(ResultCode.Accepted,s.DecideService(new(new("request:house-leave/"+s.Revision),CareerAction.RequestRelease,current.Case),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);Open(s);}Assert.Null(NewGameService.View(s.DiagnosticSnapshot()).Principal);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:house-travel/"+s.Revision,node),s.Revision).Code);At(s,s.Seconds+2);At(s,s.GetBranchView(s.PlayerControl).ArrivalAt!.Value+2);var id=new EntityId("request:house-apply/"+s.Revision);Assert.Equal(ResultCode.Accepted,s.DecideService(new(id,CareerAction.Apply,Principal:new(lord)),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);Open(s);Assert.Equal(ResultCode.Accepted,s.DecideService(new(new("request:house-accept/"+s.Revision),CareerAction.Accept,id),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);Open(s);}
    static readonly Lazy<ContractWorld> StoredReady=new(()=>MakeStored().DiagnosticSnapshot());
    static WorldSession StoredStart()=>new(ContractJson.Copy(StoredReady.Value));
    static void MoveTo(WorldSession s,EntityId site){var w=s.DiagnosticSnapshot();var node=BranchRoutes.GraphNodes(w).Single(n=>RegionalCampaign.Site(n.Id)==site);Good(s.Submit(TravelWorld.Move(w,"request:active-stored-trip/"+s.Revision,node.Id),s.Revision));At(s,s.Seconds+2);At(s,s.GetBranchView(s.PlayerControl).ArrivalAt!.Value+2);Assert.Equal(site,s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==s.PlayerControl).Site);}
    static NewMilitaryInput OrdinaryRequest(WorldSession s){var w=s.DiagnosticSnapshot();return Input(s,NewMilitaryAction.Request) with{LedgerPolicy=NewGameMilitary.LedgerIdentityContract,AuthorityPolicy=NewGameMilitary.AuthorityContract,ObservationPolicy=NewGameMilitary.ObservationContract,CycleContract=NewGameMilitary.CycleForCurrentHouse(w),FromLedger=NewGameMilitary.SourceForCurrentHouse(w),IssuerPolicy=NewGameMilitary.IssuerPolicyForRequest(w)};}
    static WorldSession MakeStored(){var s=Start();Good(s.DecideNewMilitary(OrdinaryRequest(s),s.PlayerControl,s.Revision));Permit(s);Finish(s);ChangeHouse(s,"odawara","person:ujiyasu");Good(s.DecideNewMilitary(OrdinaryRequest(s),s.PlayerControl,s.Revision));Permit(s);Finish(s);ChangeHouse(s,"kofu","person:shingen");Succeed(s);s.SetPaused(true);return s;}
    static NewMilitaryInput StoredRequest(WorldSession s){var w=s.DiagnosticSnapshot();var c=NewGameMilitary.StoredSuccessionCandidates(w).Single(c=>c.Site==Home);return NewGameMilitary.StoredSuccessionRequest(w,new("request:stored-succession/"+s.Revision),c.Ledger);}
    [Fact]public void ClosedStoredGarrisonReturnsUnderNewHeadWithBothLedgersAndOldPapersIntact(){var s=StoredStart();var before=s.DiagnosticSnapshot();var old=before.OtherMilitaryLedgers!.Single();var i=StoredRequest(s);Assert.Equal(before.NewMilitary!.Binding!.Ledger,i.FromLedger);Good(s.DecideNewMilitary(i,s.PlayerControl,s.Revision));var w=s.DiagnosticSnapshot();Assert.Equal(old.Terms,w.NewMilitary!.Terms);Assert.Equal(old.Binding!.Ledger,w.NewMilitary.Binding!.Ledger);Assert.Equal(Heir,NewGameMilitary.CasePrincipal(w));Assert.Single(w.OtherMilitaryLedgers!);Assert.Equal(before.NewMilitary.Terms,w.OtherMilitaryLedgers![0].Terms);Assert.All(before.Messaging.Messages,m=>Assert.Contains(m,w.Messaging.Messages));Assert.Equal(before.Units.OrderBy(u=>u.Id.Value).Select(u=>u.Soldiers),w.Units.OrderBy(u=>u.Id.Value).Select(u=>u.Soldiers));Assert.Equal(ContractJson.Write(before.ResourceLots.OrderBy(l=>l.Id.Value).ToArray()),ContractJson.Write(w.ResourceLots.OrderBy(l=>l.Id.Value).ToArray()));new WorldSession(w);}
    [Fact]public void StoredPermissionUsesNewHeadWhileOtherGarrisonQuantitiesStayUnchanged(){var s=StoredStart();var before=s.DiagnosticSnapshot();Good(s.DecideNewMilitary(StoredRequest(s),s.PlayerControl,s.Revision));Permit(s);var w=s.DiagnosticSnapshot();Assert.Equal(Heir,w.NewMilitary!.Authority!.Proofs.Last().Source.Issuer);Assert.Equal(Old,w.NewMilitary.Authority.Proofs[0].Source.Issuer);var other=w.OtherMilitaryLedgers!.Single();Assert.Equal(ContractJson.Write(before.NewMilitary),ContractJson.Write(other));Assert.Equal(6,w.Units.Length);Assert.Equal(200,w.Units.Sum(u=>u.Soldiers));new WorldSession(w);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void StoredRequestRejectsMissingUnknownOrWrongSourceLedger(int n){var s=StoredStart();var i=StoredRequest(s);var bad=n switch{0=>i with{TargetLedger=null},1=>i with{TargetLedger=new("ledger:missing")},_=>i with{FromLedger=new("ledger:wrong")}};var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(bad,s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void StoredReagreementRequiresTheActualHeadAtThatSameSite(){var s=StoredStart();var i=StoredRequest(s);var site=s.DiagnosticSnapshot().NewMilitary!.Terms.Site;MoveTo(s,site);Assert.Empty(NewGameMilitary.StoredSuccessionCandidates(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);}
    [Fact]public void StoredReagreementCannotLeaveAnActiveLoanInTheOtherLedger(){var s=StoredStart();Good(s.DecideNewMilitary(StoredRequest(s),s.PlayerControl,s.Revision));Permit(s);Assert.Empty(NewGameMilitary.StoredSuccessionCandidates(s.DiagnosticSnapshot()));var w=s.DiagnosticSnapshot();var other=w.OtherMilitaryLedgers!.Single();var i=NewGameMilitary.StoredSuccessionRequest(w,new("request:stored-while-active"),other.Binding!.Ledger);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);}
    [Theory][InlineData(false)][InlineData(true)]public void ASeparateNewCaseAfterActiveReturnUsesNewHeadAndStillNeedsItsOwnPermission(bool retired){var s=Holding(retired);Succeed(s);Agree(s);Send(s,NewMilitaryAction.Unload,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Finish(s);Good(s.DecideNewMilitary(Request(s),s.PlayerControl,s.Revision));Assert.Equal(Heir,NewGameMilitary.CasePrincipal(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Pickup),s.PlayerControl,s.Revision).Code);Permit(s);Assert.Equal(2,NewGameMilitary.Cases(s.DiagnosticSnapshot()).Length);Assert.Equal(Heir,s.DiagnosticSnapshot().NewMilitary!.Authority!.Proofs.Last().Source.Issuer);Assert.Equal(100,s.DiagnosticSnapshot().Units.Sum(u=>u.Soldiers));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void ActualRetiredCommanderDoesNotReceivePoliticalAuthority(){var s=Holding(true);Succeed(s);Agree(s);var w=s.DiagnosticSnapshot();Assert.Null(FactionStances.ResolveAuthority(w,Old,Owner,s.Seconds,s.Revision));Assert.All(w.NewMilitary!.Authority!.Grants,g=>Assert.Equal(Old,g.Mandate.Agent));Assert.Equal(Heir,w.NewMilitary.ActiveSuccession!.Entries.Single().Principal);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)]public void ActualGenerationRecoveryKeepsActiveCommandHistoryAndSameFuture(int phase){var s=Holding(phase%2==1);if(phase>=1)Succeed(s);if(phase>=2)Agree(s);if(phase>=3)Send(s,NewMilitaryAction.Deploy);if(phase>=4){var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Good(s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X-12000,a.Y+4000),B=new(a.X+12000,a.Y+4000)},s.PlayerControl,s.Revision));At(s,s.Seconds+3);}if(phase>=5){Send(s,NewMilitaryAction.Recall);At(s,s.Seconds+50);Send(s,NewMilitaryAction.Enter);Send(s,NewMilitaryAction.Unload,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Send(s,NewMilitaryAction.Report);}if(phase>=6){At(s,s.Seconds+2);Send(s,NewMilitaryAction.Return);}if(phase>=7){At(s,s.Seconds+2);Open(s);}Save(s,"active-military-"+phase);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ActualGenerationRecoveryKeepsBothStoredGarrisonsAndSameFuture(int phase){var s=StoredStart();if(phase>=1)Good(s.DecideNewMilitary(StoredRequest(s),s.PlayerControl,s.Revision));if(phase>=2)Permit(s);if(phase>=3)Finish(s);Save(s,"stored-military-"+phase);}
    static void Save(WorldSession s,string name){s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"active-military-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"active",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("active"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(w),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(NewGameMilitary.ViewWithAuthority(w)),ContractJson.Write(NewGameMilitary.ViewWithAuthority(b.DiagnosticSnapshot())));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){File.WriteAllBytes(Path.Combine(dir,name+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,name+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}foreach(var x in new[]{s,b})At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));}
    [Fact]public void StoredUnitsUseTheirOwnLedgerSitePositions(){var s=StoredStart();var w=s.DiagnosticSnapshot();foreach(var ledger in NewGameMilitary.LedgerStates(w)){var node=BranchRoutes.GraphNodes(w).Single(n=>RegionalCampaign.Site(n.Id)==ledger.Terms.Site);var anchor=FieldWorld.FromWorld(node.Position);for(int i=0;i<3;i++)Assert.Equal(new FieldPoint(anchor.X,anchor.Y+(i==0?0:i==1?8000:-8000)),NewGameMilitary.ManagedUnitPosition(w,ledger.Binding!.Units[i],w.ElapsedSeconds));}Assert.Null(NewGameMilitary.ManagedUnitPosition(w,new("unit:unknown"),w.ElapsedSeconds));}
}
